import sys
import math

def max_fruits_sliced(n, fruits):
    def distance_to_line(x0, y0, x1, y1, cx, cy):
        # Handle vertical line case
        if x1 == x0:
            return abs(cx - x0)
        # General case
        m = (y1 - y0) / (x1 - x0)
        c = y0 - m * x0
        return abs(m * cx - cy + c) / math.sqrt(m**2 + 1)

    max_sliced = 0
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = fruits[i]
            x2, y2 = fruits[j]
            sliced = 0
            for k in range(n):
                cx, cy = fruits[k]
                if distance_to_line(x1, y1, x2, y2, cx, cy) <= 1.0:
                    sliced += 1
            max_sliced = max(max_sliced, sliced)

    return max_sliced

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    fruits = []
    index = 1
    for _ in range(n):
        x = float(data[index])
        y = float(data[index + 1])
        fruits.append((x, y))
        index += 2

    result = max_fruits_sliced(n, fruits)
    print(result)

